"use client";

import { useEffect, useState, useMemo } from "react";
import { useLanguage } from "@/lib/i18n/LanguageContext";
import { ErrorState } from "@/components/ui/error-state";
import { createClient } from "@/lib/supabase";
import { useRouter } from "next/navigation";
import { cn } from "@/lib/utils";
import { ArrowUpRight, Users, DollarSign, TrendingDown, Clock, Target, AlertTriangle } from "lucide-react";

interface Lead {
  id: string; customer_name: string | null;
  stage: string; quotation_value: number | null;
  win_probability: number | null;
  last_contact_date: string | null; created_at: string; updated_at: string;
  next_followup_date: string | null;
  recovery_candidate: boolean; transfer_candidate: boolean;
  sales_manager_review: boolean; hold_since: string | null;
  lead_status: string | null;
}

function fmtAED(v: number): string {
  if (v >= 1_000_000) return `AED ${(v / 1_000_000).toFixed(1)}M`;
  if (v >= 1_000) return `AED ${(v / 1_000).toFixed(0)}K`;
  return `AED ${v.toLocaleString()}`;
}

function daysSince(d: string | null): number | null {
  if (!d) return null;
  return Math.floor((Date.now() - new Date(d).getTime()) / 86_400_000);
}

export default function PipelinePage() {
  const supabase = createClient();
  const router = useRouter();
  const { t } = useLanguage();
  const [leads, setLeads] = useState<Lead[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const STAGES = [
    { key: "new", label: "New Lead", color: "#6B7280", desc: t("stageLabels.new") },
    { key: "contacted", label: "Contacted", color: "#C48A52", desc: t("stageLabels.contacted") },
    { key: "requirement_confirmed", label: "Req Confirmed", color: "#E0B95A", desc: t("stageLabels.requirement_confirmed") },
    { key: "solution_submitted", label: "Solution Sub.", color: "#9B2D5E", desc: t("stageLabels.solution_submitted") },
    { key: "quotation_submitted", label: "Quotation Sub.", color: "#8B5CF6", desc: t("stageLabels.quotation_submitted") },
    { key: "negotiation", label: "Negotiation", color: "#3B82F6", desc: t("stageLabels.negotiation") },
    { key: "pending_decision", label: "Pending Decision", color: "#F59E0B", desc: t("stageLabels.pending_decision") },
    { key: "won", label: "Won", color: "#4ADE80", desc: t("stageLabels.won") },
    { key: "lost", label: "Lost", color: "#6B7280", desc: t("stageLabels.lost") },
  ];

  useEffect(() => {
    (async () => {
      const { data, error: err } = await supabase.from("leads").select("*").limit(500);
      if (err) {
        console.error("Failed to fetch leads:", err);
        setError("加载失败，请刷新重试");
        setLoading(false);
        return;
      }
      if (data) setLeads(data as Lead[]);
      setLoading(false);
    })();
  }, []);

  const analysis = useMemo(() => {
    // Per-stage analysis
    const stageData = STAGES.map(s => {
      const items = leads.filter(l => l.stage === s.key);
      const count = items.length;
      const value = items.reduce((sum, l) => sum + (l.quotation_value || 0), 0);
      const avgProb = count > 0 ? Math.round(items.reduce((sum, l) => sum + (l.win_probability || 0), 0) / count) : 0;
      const weightedValue = items.reduce((sum, l) => sum + (l.quotation_value || 0) * (l.win_probability || 0) / 100, 0);
      const staleCount = items.filter(l => {
        const d = daysSince(l.last_contact_date || l.updated_at);
        return d !== null && d >= 7;
      }).length;
      const hotCount = items.filter(l => l.lead_status === "hot").length;
      const recoveryCount = items.filter(l => l.recovery_candidate).length;
      const transferCount = items.filter(l => l.transfer_candidate).length;
      const reviewCount = items.filter(l => l.sales_manager_review).length;
      const pendingStaleCount = s.key === "pending_decision" ? items.filter(l => {
        const d = daysSince(l.hold_since || l.updated_at);
        return d !== null && d >= 30;
      }).length : 0;

      return { key: s.key, label: s.label, color: s.color, desc: s.desc,
        count, value, avgProb, weightedValue, staleCount, hotCount,
        recoveryCount, transferCount, reviewCount, pendingStaleCount };
    });

    // Drop-off analysis: from stage → next stage
    const dropOffs = [];
    for (let i = 0; i < STAGES.length - 2; i++) { // exclude won/lost
      const from = stageData[i];
      const to = stageData[i + 1];
      if (from.count > 0) {
        const rate = Math.round((to.count / from.count) * 100);
        dropOffs.push({ from: from.label, to: to.label, fromCount: from.count, toCount: to.count, rate, dropOff: 100 - rate });
      }
    }

    // Totals
    const pipeline = stageData.filter(s => s.key !== "won" && s.key !== "lost");
    const totalPipeline = pipeline.reduce((sum, s) => sum + s.value, 0);
    const totalWeighted = pipeline.reduce((sum, s) => sum + s.weightedValue, 0);
    const totalActive = pipeline.reduce((sum, s) => sum + s.count, 0);
    const totalStale = pipeline.reduce((sum, s) => sum + s.staleCount, 0);
    const wonCount = stageData.find(s => s.key === "won")?.count || 0;
    const lostCount = stageData.find(s => s.key === "lost")?.count || 0;

    // Probability-weighted pipeline chart data
    const probDistribution = [10, 30, 50, 70, 90].map(p => {
      const items = leads.filter(l => l.win_probability === p && !["won", "lost"].includes(l.stage));
      return { probability: p, count: items.length, value: items.reduce((sum, l) => sum + (l.quotation_value || 0), 0) };
    });

    return { stageData, dropOffs, totalPipeline, totalWeighted, totalActive, totalStale, wonCount, lostCount, probDistribution };
  }, [leads, t]);

  if (loading) return <div className="text-center py-16 text-muted-foreground">{t("common.loading")}</div>;
  if (error) return <ErrorState message={error} onRetry={() => window.location.reload()} />;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-foreground tracking-tight">{t("pipeline.title")}</h1>
        <p className="text-muted-foreground text-sm mt-0.5">
          {analysis.totalActive} {t("pipeline.totalCount")} · {t("pipeline.totalPipeline")} {fmtAED(analysis.totalPipeline)} · {t("pipeline.weightedValue")} {fmtAED(analysis.totalWeighted)}
        </p>
      </div>

      {/* Summary cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <div className="p-4 rounded-xl border border-border/50 bg-gradient-to-br from-emerald-500/5 to-transparent">
          <p className="text-xs text-muted-foreground">{t("stageLabels.won")}</p>
          <p className="text-2xl font-bold text-emerald-400">{analysis.wonCount}</p>
        </div>
        <div className="p-4 rounded-xl border border-border/50 bg-gradient-to-br from-red-500/5 to-transparent">
          <p className="text-xs text-muted-foreground">{t("stageLabels.lost")}</p>
          <p className="text-2xl font-bold text-red-400">{analysis.lostCount}</p>
        </div>
        <div className="p-4 rounded-xl border border-border/50 bg-gradient-to-br from-amber-500/5 to-transparent">
          <p className="text-xs text-muted-foreground">{t("pipeline.stale")}</p>
          <p className="text-2xl font-bold text-amber-400">{analysis.totalStale}</p>
        </div>
        <div className="p-4 rounded-xl border border-border/50 bg-gradient-to-br from-copper-500/5 to-transparent">
          <p className="text-xs text-muted-foreground">{t("pipeline.weightedValue")}</p>
          <p className="text-2xl font-bold text-copper-400">{fmtAED(analysis.totalWeighted)}</p>
        </div>
      </div>

      {/* 9-stage Funnel */}
      <div className="rounded-xl border border-border/50 p-5">
        <div className="flex items-center gap-2 mb-4">
          <TrendingDown className="w-4 h-4 text-muted-foreground" />
          <h3 className="text-sm font-semibold text-foreground">{t("pipeline.subtitle")}</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-border/50">
                <th className="text-left py-2 pr-4 text-muted-foreground font-medium">{t("pipeline.subtitle")}</th>
                <th className="text-right py-2 px-3 text-muted-foreground font-medium">{t("pipeline.count")}</th>
                <th className="text-right py-2 px-3 text-muted-foreground font-medium">{t("pipeline.value")} (AED)</th>
                <th className="text-right py-2 px-3 text-muted-foreground font-medium">{t("pipeline.avgProb")}</th>
                <th className="text-right py-2 px-3 text-muted-foreground font-medium">{t("pipeline.weightedValue")}</th>
                <th className="text-right py-2 px-3 text-muted-foreground font-medium">{t("pipeline.hot")}</th>
                <th className="text-right py-2 px-3 text-muted-foreground font-medium">{t("pipeline.stale")}</th>
                <th className="text-right py-2 px-3 text-muted-foreground font-medium">{t("pipeline.recovery")}.</th>
                <th className="text-right py-2 px-3 text-muted-foreground font-medium">{t("pipeline.transfer")}.</th>
                <th className="text-right py-2 px-3 text-muted-foreground font-medium">{t("pipeline.review")}</th>
              </tr>
            </thead>
            <tbody>
              {analysis.stageData.map((s, i) => {
                const maxCount = Math.max(...analysis.stageData.map(x => x.count), 1);
                const barWidth = Math.max((s.count / maxCount) * 100, s.count > 0 ? 3 : 0);
                return (
                  <tr key={s.key}
                    className={cn("border-b border-border/20 hover:bg-accent/30 cursor-pointer transition-colors",
                      s.key === "won" ? "bg-emerald-950/10" : s.key === "lost" ? "bg-red-950/10" : "")}
                    onClick={() => router.push(`/leads?stage=${s.key}`)}
                  >
                    <td className="py-3 pr-4">
                      <div className="flex items-center gap-2">
                        <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: s.color }} />
                        <span className="font-medium">{s.label}</span>
                        <span className="text-[10px] text-muted-foreground">{s.desc}</span>
                      </div>
                    </td>
                    <td className="text-right py-3 px-3">
                      <span className="font-semibold">{s.count}</span>
                      <div className="h-1.5 bg-muted rounded-full mt-1 w-20 ml-auto">
                        <div className="h-full rounded-full" style={{ width: `${barWidth}%`, backgroundColor: s.color, opacity: 0.7 }} />
                      </div>
                    </td>
                    <td className="text-right py-3 px-3 text-copper-400 font-medium">{s.value > 0 ? fmtAED(s.value) : "—"}</td>
                    <td className="text-right py-3 px-3">
                      <span className={cn(s.avgProb >= 70 ? "text-emerald-400" : s.avgProb >= 30 ? "text-amber-400" : "text-gray-400")}>
                        {s.avgProb > 0 ? `${s.avgProb}%` : "—"}
                      </span>
                    </td>
                    <td className="text-right py-3 px-3 text-copper-400">{s.weightedValue > 0 ? fmtAED(s.weightedValue) : "—"}</td>
                    <td className="text-right py-3 px-3 text-rose-400">{s.hotCount > 0 ? s.hotCount : "—"}</td>
                    <td className="text-right py-3 px-3 text-amber-400">{s.staleCount > 0 ? s.staleCount : "—"}</td>
                    <td className="text-right py-3 px-3 text-orange-400">{s.recoveryCount > 0 ? s.recoveryCount : "—"}</td>
                    <td className="text-right py-3 px-3 text-red-400">{s.transferCount > 0 ? s.transferCount : "—"}</td>
                    <td className="text-right py-3 px-3 text-purple-400">
                      {s.reviewCount + s.pendingStaleCount > 0 ? s.reviewCount + s.pendingStaleCount : "—"}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Drop-off Analysis */}
      <div className="rounded-xl border border-border/50 p-5">
        <div className="flex items-center gap-2 mb-4">
          <TrendingDown className="w-4 h-4 text-red-400" />
          <h3 className="text-sm font-semibold text-foreground">{t("pipeline.dropOff")}</h3>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
          {analysis.dropOffs.map((d, i) => {
            const barColor = d.dropOff > 60 ? "#ef4444" : d.dropOff > 30 ? "#f59e0b" : "#4ade80";
            return (
              <div key={i} className="p-4 rounded-xl bg-muted/20 border border-border/30">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-xs text-muted-foreground">{d.from} → {d.to}</span>
                  <span className={cn("text-lg font-bold", d.rate >= 50 ? "text-emerald-400" : d.rate >= 20 ? "text-amber-400" : "text-red-400")}>
                    {d.rate}%
                  </span>
                </div>
                <div className="h-2 bg-muted rounded-full overflow-hidden">
                  <div className="h-full rounded-full transition-all" style={{ width: `${d.rate}%`, backgroundColor: barColor, opacity: 0.7 }} />
                </div>
                <div className="flex justify-between mt-1 text-[10px] text-muted-foreground">
                  <span>{d.fromCount} → {d.toCount}</span>
                  <span>{t("pipeline.dropOff")} {d.dropOff}%</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Probability Distribution */}
      <div className="rounded-xl border border-border/50 p-5">
        <div className="flex items-center gap-2 mb-4">
          <Target className="w-4 h-4 text-muted-foreground" />
          <h3 className="text-sm font-semibold text-foreground">{t("pipeline.avgProb")}</h3>
        </div>
        <div className="grid grid-cols-5 gap-3">
          {analysis.probDistribution.map(pd => {
            const maxVal = Math.max(...analysis.probDistribution.map(x => x.value), 1);
            return (
              <div key={pd.probability} className="text-center p-3 rounded-lg bg-muted/20 border border-border/30">
                <p className={cn("text-lg font-bold",
                  pd.probability >= 70 ? "text-emerald-400" : pd.probability >= 30 ? "text-amber-400" : "text-gray-400")}>
                  {pd.probability}%
                </p>
                <div className="h-16 flex items-end justify-center my-2">
                  <div className="w-full rounded-t-md transition-all" style={{
                    height: `${Math.max((pd.value / maxVal) * 100, pd.count > 0 ? 8 : 0)}%`,
                    backgroundColor: pd.probability >= 70 ? "#4ade80" : pd.probability >= 30 ? "#f59e0b" : "#6b7280",
                    opacity: 0.6,
                  }} />
                </div>
                <p className="text-xs font-semibold">{pd.count}</p>
                <p className="text-[10px] text-muted-foreground">{pd.value > 0 ? fmtAED(pd.value) : "—"}</p>
              </div>
            );
          })}
        </div>
      </div>

      {/* Stale Leads by Stage */}
      <div className="rounded-xl border border-border/50 p-5">
        <div className="flex items-center gap-2 mb-4">
          <Clock className="w-4 h-4 text-amber-400" />
          <h3 className="text-sm font-semibold text-foreground">{t("pipeline.stale")}</h3>
        </div>
        <div className="space-y-2">
          {analysis.stageData.filter(s => s.staleCount > 0).map(s => {
            const maxStale = Math.max(...analysis.stageData.map(x => x.staleCount), 1);
            return (
              <div key={s.key} className="flex items-center gap-3">
                <span className="w-28 text-xs text-muted-foreground text-right">{s.label}</span>
                <div className="flex-1 h-6 bg-muted rounded overflow-hidden">
                  <div className="h-full rounded flex items-center px-2 transition-all"
                    style={{ width: `${(s.staleCount / maxStale) * 100}%`, backgroundColor: s.color, opacity: 0.7 }}>
                    <span className="text-xs font-semibold text-white">{s.staleCount}</span>
                  </div>
                </div>
                <span className="text-xs text-muted-foreground w-16">
                  {s.count > 0 ? `${Math.round((s.staleCount / s.count) * 100)}%` : ""}
                </span>
              </div>
            );
          })}
          {analysis.stageData.every(s => s.staleCount === 0) && (
            <p className="text-sm text-muted-foreground text-center py-4">{t("pipeline.totalCount")} 🎉</p>
          )}
        </div>
      </div>
    </div>
  );
}
